      "path": "src/lib/useCounter.test.tsx",
      "content": "import { renderHook, act } from '@testing-library/react';
import { useCounter } from './useCounter';

describe('useCounter', () => {
  beforeEach(() => {
    window.localStorage.clear();
  });

  it('should initialize to 0 if no value in localStorage', () => {
    const { result } = renderHook(() => useCounter());
    expect(result.current.count).toBe(0);
  });

  it('should restore count from localStorage', () => {
    window.localStorage.setItem('counter.count', '5');
    const { result } = renderHook(() => useCounter());
    expect(result.current.count).toBe(5);
  });

  it('should increment, decrement, and reset', () => {
    const { result } = renderHook(() => useCounter());
    act(() => result.current.increment());
    expect(result.current.count).toBe(1);
    act(() => result.current.decrement());
    expect(result.current.count).toBe(0);
    act(() => result.current.decrement());
    expect(result.current.count).toBe(0);
    act(() => result.current.increment());
    act(() => result.current.increment());
    act(() => result.current.reset());
    expect(result.current.count).toBe(0);
  });

  it('should persist count to localStorage', () => {
    const { result } = renderHook(() => useCounter());
    act(() => result.current.increment());
    expect(window.localStorage.getItem('counter.count')).toBe('1');
  });

  it('should handle localStorage errors gracefully', () => {
    const originalSetItem = window.localStorage.setItem;
    window.localStorage.setItem = () => { throw new Error('fail'); };
    const { result } = renderHook(() => useCounter());
    act(() => result.current.increment());
    expect(result.current.count).toBe(1);
    window.localStorage.setItem = originalSetItem;
  });
});
